function routeLogin(config) {
  return function (req, res) {
    const credential = config.credentials.find(
      (c) => safeEqual(req.body.username, c.username) && safeEqual(req.body.password, c.password));
    if (credential) {
      req.session.loggedIn = true;
      req.session.username = credential.username;
      res.json({ status: 1, message: config.lang.api.loginSuccessful });
      return;
    }
    res.json({ status: 0, message: config.lang.api.invalidCredentials });
  };
}

function routeLogout(config) {
  return function (req, res) {
    req.session.destroy((err) => {
      if (err) console.error('Error destroying session:', err);
      res.clearCookie(config.session_name);
      res.redirect(`${config.base_url}/`);
    });
  };
}

